import{_ as r,a0 as s,w as l,s as m,ao as p,I as i,x as t,a1 as n,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"使用自动化时的五个常见错误 | LCTT x X-CMD","titleTemplate":false,"description":"使用自动化时的五个常见错误 | LCTT (202205) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用自动化时的五个常见错误 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用自动化时的五个常见错误 | LCTT (202205) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202205/20220518 Five common mistakes when using automation","title":"使用自动化时的五个常见错误","tag":"202205","desc":""},"relativePath":"202205/20220518 Five common mistakes when using automation.md","filePath":"[post].md"}'),d={name:"202205/20220518 Five common mistakes when using automation.md"};function u(h,a,f,g,T,b){const e=s("Link");return l(),m("div",null,[a[15]||(a[15]=p('<h1 id="使用自动化时的五个常见错误" tabindex="-1">使用自动化时的五个常见错误 <a class="header-anchor" href="#使用自动化时的五个常见错误" aria-label="Permalink to “使用自动化时的五个常见错误”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202205/31/151450ukwk98weqgefgowa.jpg" alt=""></p><p>随着自动化扩展到涵盖 IT 的更多方面，越来越多的管理员正在学习自动化技能并应用它们来减轻他们的工作量。自动化可以减轻重复性任务的负担，并为基础设施增加一定程度的一致性。但是，当 IT 工作人员部署自动化时，会出现可能对大大小小的基础设施造成严重破坏的常见错误。在自动化部署中通常会出现五个常见错误。</p><h3 id="缺乏测试" tabindex="-1">缺乏测试 <a class="header-anchor" href="#缺乏测试" aria-label="Permalink to “缺乏测试”">​</a></h3><p>初学者常犯的错误是自动化脚本没有经过全面测试。由于拼写错误或逻辑错误，简单的 shell 脚本可能会对服务器产生不利影响。将该错误乘以基础架构中的服务器数量，你可能会遇到一大堆问题需要清理。在大规模部署之前始终测试你的自动化脚本。</p><h3 id="意外负载" tabindex="-1">意外负载 <a class="header-anchor" href="#意外负载" aria-label="Permalink to “意外负载”">​</a></h3><p>经常发生的第二个错误是没有预测脚本可能对其他资源施加的系统负载。当目标是十几个服务器时，运行从仓库下载文件或安装包的脚本可能没问题。脚本通常在成百上千台服务器上运行。这种负载可以使支持服务停止或完全崩溃。不要忘记考虑端点影响或设置合理的并发率。</p><h3 id="离开脚本" tabindex="-1">离开脚本 <a class="header-anchor" href="#离开脚本" aria-label="Permalink to “离开脚本”">​</a></h3><p>自动化工具的一种用途是确保符合标准设置。自动化可以轻松确保组中的每台服务器都具有完全相同的设置。如果该组中的服务器需要根据该基线进行更改，同时管理员不了解合规标准，那么可能会出现问题。安装和启用不需要和不想要的服务，从而导致可能的安全问题。</p><h3 id="缺乏文档" tabindex="-1">缺乏文档 <a class="header-anchor" href="#缺乏文档" aria-label="Permalink to “缺乏文档”">​</a></h3><p>管理员的一项固定职责应该是记录他们的工作。由于合同到期、升职或定期员工流动，公司可能会在 IT 部门频繁招聘新员工。公司内的工作组相互隔离也很常见。由于这些原因，重要的是记录哪些自动化已经到位。与用户运行脚本不同，自动化可能会在创建它的人离开组之后继续很长时间。管理员可能会发现自己在其基础设施中面临着来自未经检查的自动化的奇怪行为。</p><h3 id="缺乏经验" tabindex="-1">缺乏经验 <a class="header-anchor" href="#缺乏经验" aria-label="Permalink to “缺乏经验”">​</a></h3><p>列表中的最后一个错误是管理员对他们正在自动化的系统不够了解。管理员经常被雇用到他们没有接受过足够培训且没有人可以求教的职位上工作。自 COVID 以来，当公司努力填补空缺时，这一点尤其重要。然后管理员被迫处理他们没有设置并且可能不完全理解的基础设施。这可能会导致非常低效的脚本浪费资源或配置错误的服务器。</p><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>越来越多的管理员正在学习自动化来帮助他们完成日常任务。因此，自动化正被应用于更多的技术领域。希望此列表将有助于防止新用户犯这些错误，并敦促经验丰富的管理员重新评估他们的 IT 策略。自动化旨在减轻重复性任务的负担，而不是为最终用户带来更多工作。</p><hr>',16)),i("p",null,[a[1]||(a[1]=t("via: ",-1)),n(e,{href:"https://fedoramagazine.org/five-common-mistakes-when-using-automation/"},{default:o(()=>[...a[0]||(a[0]=[t("https://fedoramagazine.org/five-common-mistakes-when-using-automation/",-1)])]),_:1})]),i("p",null,[a[6]||(a[6]=t("作者：",-1)),n(e,{href:"https://fedoramagazine.org/author/gscarbor/"},{default:o(()=>[...a[2]||(a[2]=[t("Gary Scarborough",-1)])]),_:1}),a[7]||(a[7]=t(" 选题：",-1)),n(e,{href:"https://github.com/lujun9972"},{default:o(()=>[...a[3]||(a[3]=[t("lujun9972",-1)])]),_:1}),a[8]||(a[8]=t(" 译者：",-1)),n(e,{href:"https://github.com/geekpi"},{default:o(()=>[...a[4]||(a[4]=[t("geekpi",-1)])]),_:1}),a[9]||(a[9]=t(" 校对：",-1)),n(e,{href:"https://github.com/wxy"},{default:o(()=>[...a[5]||(a[5]=[t("wxy",-1)])]),_:1})]),i("p",null,[a[12]||(a[12]=t("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...a[10]||(a[10]=[t("LCTT",-1)])]),_:1}),a[13]||(a[13]=t(" 原创编译，",-1)),n(e,{href:"https://linux.cn/"},{default:o(()=>[...a[11]||(a[11]=[t("Linux中国",-1)])]),_:1}),a[14]||(a[14]=t(" 荣誉推出",-1))])])}const w=r(d,[["render",u]]);export{C as __pageData,w as default};
